draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw kimchi
  ctx.fillStyle = '#ff99cc';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // Draw sauerkraut
  ctx.fillStyle = '#cccccc';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw probiotic bacteria
  ctx.fillStyle = '#66cc00';
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20 * Math.sin(t), H/2 - 20 + 20 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 170);
  ctx.lineTo(W/2, H/2 + 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 - 30, H/2 + 230);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 + 30, H/2 + 230);
  ctx.stroke();

  // Draw smiling face
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 140, 10, 0, Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 + 130);
  ctx.lineTo(W/2 + 10, H/2 + 150);
  ctx.stroke();

  ctx.restore();
}
